// ── Types ────────────────────────────────────────────────────────────────────
type Verdict = "malicious" | "suspicious" | "clean" | "unknown";
type ObsType = "ip" | "domain" | "url" | "sha256" | "md5" | "sha1" | "cve" | "email" | "keyword" | "unknown";

interface SourceResult { found: boolean; source?: string; [key: string]: any }
interface EnrichResult {
  value: string; type: ObsType; verdict: Verdict;
  positives: number; total: number; score?: number;
  results: Record<string, SourceResult>;
  internalHits: any[];
}

// ── Observable type detection ─────────────────────────────────────────────────
function detectType(v: string): ObsType {
  const s = v.trim();
  if (/^CVE-\d{4}-\d{4,7}$/i.test(s)) return "cve";
  if (/^[a-f0-9]{64}$/i.test(s)) return "sha256";
  if (/^[a-f0-9]{40}$/i.test(s)) return "sha1";
  if (/^[a-f0-9]{32}$/i.test(s)) return "md5";
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(s)) return "ip";
  if (/^https?:\/\//i.test(s)) return "url";
  if (/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s)) return "email";
  if (/^([a-z0-9-]+\.)+[a-z]{2,}$/i.test(s)) return "domain";
  // Company name, keyword, or multi-word phrase → breach/leak search
  if (s.length >= 2 && /^[a-zA-Z0-9 .,'_@#&()\-]+$/.test(s)) return "keyword";
  return "unknown";
}

// Guess a company's primary domain from a keyword (e.g. "micron" → "micron.com")
function guessDomain(keyword: string): string {
  const clean = keyword.trim().toLowerCase().split(/\s+/)[0].replace(/[^a-z0-9-]/g, "");
  return `${clean}.com`;
}

// ── Safe browser fetch wrapper ────────────────────────────────────────────────
async function api(url: string, opts: RequestInit = {}, timeout = 12000): Promise<any> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeout);
    const res = await fetch(url, { signal: ctrl.signal, ...opts });
    clearTimeout(t);
    if (!res.ok) return null;
    const ct = res.headers.get("content-type") || "";
    return ct.includes("json") ? res.json() : res.text();
  } catch { return null; }
}

// ── Individual source lookups (all CORS-enabled, browser-safe) ────────────────
async function fromThreatFox(value: string, type: ObsType): Promise<SourceResult> {
  const body: any = { query: "search_ioc", search_term: value };
  if (type === "sha256" || type === "md5") { body.query = "search_hash"; body.hash = value; delete body.search_term; }
  const d = await api("https://threatfox-api.abuse.ch/api/v1/", {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
  });
  if (!d || d.query_status === "no_result" || !d.data?.length) return { found: false, source: "ThreatFox" };
  const hit = d.data[0];
  return {
    found: true, source: "ThreatFox (Abuse.ch)",
    malware: hit.malware_printable, threat_type: hit.threat_type_desc,
    confidence: hit.confidence_level, first_seen: hit.first_seen,
    tags: Array.isArray(hit.tags) ? hit.tags : hit.tags ? [String(hit.tags)] : [], total_iocs: d.data.length,
    reporter: hit.reporter,
  };
}

async function fromURLhaus(value: string, type: ObsType): Promise<SourceResult> {
  const form = new URLSearchParams();
  if (type === "url") form.set("url", value);
  else if (type === "domain" || type === "ip") form.set("host", value);
  else if (type === "md5") form.set("md5_hash", value);
  else return { found: false, source: "URLhaus" };
  const d = await api("https://urlhaus-api.abuse.ch/v1/url/", {
    method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: form.toString(),
  });
  if (!d || d.query_status === "no_results") return { found: false, source: "URLhaus" };
  return {
    found: true, source: "URLhaus (Abuse.ch)",
    url_status: d.url_status, threat: d.threat, tags: Array.isArray(d.tags) ? d.tags : d.tags ? [String(d.tags)] : [],
    date_added: d.date_added, host: d.host,
    payloads: (d.payloads || []).slice(0, 3),
  };
}

async function fromMalwareBazaar(hash: string): Promise<SourceResult> {
  const d = await api("https://mb-api.abuse.ch/api/v1/", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ query: "get_info", hash }),
  });
  if (!d || d.query_status !== "ok" || !d.data?.[0]) return { found: false, source: "MalwareBazaar" };
  const s = d.data[0];
  return {
    found: true, source: "MalwareBazaar (Abuse.ch)",
    file_name: s.file_name, file_type: s.file_type, file_size: `${s.file_size} bytes`,
    signature: s.signature, tags: Array.isArray(s.tags) ? s.tags : s.tags ? [String(s.tags)] : [], first_seen: s.first_seen,
    reporter: s.reporter, mime_type: s.mime_type,
    sha256: s.sha256_hash, md5: s.md5_hash,
  };
}

async function fromNVD(cveId: string): Promise<SourceResult> {
  const d = await api(`https://services.nvd.nist.gov/rest/json/cves/2.0?cveId=${encodeURIComponent(cveId)}`, {}, 20000);
  if (!d?.vulnerabilities?.length) return { found: false, source: "NVD / NIST" };
  const cve = d.vulnerabilities[0].cve;
  const desc = cve.descriptions?.find((x: any) => x.lang === "en")?.value || "";
  const v31 = cve.metrics?.cvssMetricV31?.[0]?.cvssData;
  const v30 = cve.metrics?.cvssMetricV30?.[0]?.cvssData;
  const cvss = v31 || v30;
  return {
    found: true, source: "NVD / NIST",
    description: desc, cvss_score: cvss?.baseScore,
    cvss_severity: cvss?.baseSeverity, cvss_vector: cvss?.vectorString,
    published: cve.published, modified: cve.lastModified,
    cisa_kev: !!cve.cisaExploitAdd, cisa_kev_date: cve.cisaExploitAdd,
    references: (cve.references || []).slice(0, 8).map((r: any) => r.url),
    cpe: (cve.configurations?.[0]?.nodes?.[0]?.cpeMatch || []).slice(0, 5).map((c: any) => c.criteria),
    weaknesses: (cve.weaknesses?.[0]?.description || []).map((w: any) => w.value).join(", "),
  };
}

async function fromEPSS(cveId: string): Promise<SourceResult> {
  const d = await api(`https://api.first.org/data/v1/epss?cve=${encodeURIComponent(cveId)}`);
  if (!d?.data?.[0]) return { found: false, source: "EPSS" };
  const e = d.data[0];
  const pct = (parseFloat(e.epss) * 100).toFixed(2);
  const perc = (parseFloat(e.percentile) * 100).toFixed(1);
  return {
    found: true, source: "FIRST.org EPSS",
    epss_score: parseFloat(e.epss), percentile: parseFloat(e.percentile),
    exploitation_probability: `${pct}% chance of exploitation in next 30 days`,
    percentile_rank: `Higher risk than ${perc}% of all CVEs`,
    date: e.date,
  };
}

async function fromGreyNoise(ip: string): Promise<SourceResult> {
  const d = await api(`https://api.greynoise.io/v3/community/${ip}`, {}, 10000);
  if (!d || d.message === "Not Found") return { found: false, source: "GreyNoise" };
  const isMalicious = d.classification === "malicious";
  const isNoise = d.noise === true;
  const isRiot = d.riot === true;
  // noise=true means IP is actively scanning/attacking internet — flag as suspicious
  // riot=true means KNOWN BENIGN (Google, Cloudflare, etc.) — NOT malicious
  return {
    found: isMalicious || (isNoise && !isRiot),
    riot_benign: isRiot,
    source: "GreyNoise Community",
    noise: d.noise, riot: d.riot, classification: d.classification || (isNoise ? "noise/scanner" : "unclassified"),
    name: d.name, last_seen: d.last_seen, link: d.link,
    note: isRiot ? "Known benign infrastructure (CDN/scanner) — reduces suspicion" :
          isMalicious ? "Classified as MALICIOUS by GreyNoise" :
          isNoise ? "Internet scanner/crawler — actively probing internet hosts" : undefined,
  };
}

