// ── Domain/Company breach intelligence ───────────────────────────────────────

// HIBP domain breach — PUBLIC endpoint, no API key needed
async function fromHIBPDomain(domain: string): Promise<SourceResult> {
  const d = await api(`https://haveibeenpwned.com/api/v3/breaches?domain=${encodeURIComponent(domain)}`, {}, 15000);
  if (!Array.isArray(d) || !d.length) return { found: false, source: "HaveIBeenPwned (Domain)" };
  const sorted = [...d].sort((a: any, b: any) => new Date(b.BreachDate).getTime() - new Date(a.BreachDate).getTime());
  const allClasses: string[] = [...new Set(d.flatMap((b: any) => b.DataClasses || []))];
  const totalPwned = d.reduce((sum: number, b: any) => sum + (b.PwnCount || 0), 0);
  return {
    found: true,
    source: "HaveIBeenPwned (Domain Breaches)",
    breach_count: d.length,
    total_accounts_compromised: totalPwned.toLocaleString(),
    data_classes_exposed: allClasses.join(", "),
    passwords_exposed: allClasses.includes("Passwords") ? "YES" : "No",
    source_code_exposed: allClasses.some(c => c.toLowerCase().includes("source code")) ? "YES" : "No",
    auth_tokens_exposed: allClasses.some(c => c.toLowerCase().includes("token")) ? "YES" : "No",
    most_recent_breach: sorted[0]?.Name,
    most_recent_date: sorted[0]?.BreachDate,
    breaches: sorted.slice(0, 10).map((b: any) => `${b.Title} (${b.BreachDate}, ${b.PwnCount?.toLocaleString()} accounts)`).join(" | "),
    _breachList: sorted,
  };
}

// HIBP all-breaches filtered by company name — for keyword searches like "micron"
async function fromHIBPKeyword(keyword: string): Promise<SourceResult> {
  const all = await api("https://haveibeenpwned.com/api/v3/breaches", {}, 20000);
  if (!Array.isArray(all)) return { found: false, source: "HaveIBeenPwned (Search)" };
  const q = keyword.toLowerCase().replace(/\.(com|org|net|io|gov|edu)$/i, "").trim();
  const matches = all.filter((b: any) =>
    (b.Name || "").toLowerCase().includes(q) ||
    (b.Title || "").toLowerCase().includes(q) ||
    (b.Domain || "").toLowerCase().includes(q) ||
    (b.Description || "").toLowerCase().includes(q)
  );
  if (!matches.length) return { found: false, source: "HaveIBeenPwned (Search)" };
  const sorted = [...matches].sort((a: any, b: any) => new Date(b.BreachDate).getTime() - new Date(a.BreachDate).getTime());
  const allClasses: string[] = [...new Set(matches.flatMap((b: any) => b.DataClasses || []))];
  const totalPwned = matches.reduce((sum: number, b: any) => sum + (b.PwnCount || 0), 0);
  return {
    found: true,
    source: "HaveIBeenPwned (Company/Keyword Search)",
    breach_count: matches.length,
    total_accounts_compromised: totalPwned.toLocaleString(),
    data_classes_exposed: allClasses.join(", "),
    passwords_exposed: allClasses.includes("Passwords") ? "YES" : "No",
    source_code_exposed: allClasses.some(c => c.toLowerCase().includes("source code")) ? "YES" : "No",
    most_recent_breach: sorted[0]?.Title,
    most_recent_date: sorted[0]?.BreachDate,
    breaches: sorted.slice(0, 10).map((b: any) => `${b.Title} [${b.Domain || "—"}] (${b.BreachDate}, ${b.PwnCount?.toLocaleString()} accounts)`).join(" | "),
    _breachList: sorted,
  };
}

// Hudson Rock domain — employee credential stealer logs
async function fromHudsonRockDomain(domain: string): Promise<SourceResult> {
  const d = await api(
    `https://cavalier.hudsonrock.com/api/json/v2/osint-tools/search-by-domain?domain=${encodeURIComponent(domain)}`,
    {}, 15000
  );
  if (!d) return { found: false, source: "Hudson Rock Cavalier" };
  const employees = Array.isArray(d.employees) ? d.employees : [];
  const clients   = Array.isArray(d.clients)   ? d.clients   : [];
  const total = employees.length + clients.length;
  if (!total) return { found: false, source: "Hudson Rock Cavalier", note: "No employee/client stealer logs found" };
  const sample = employees[0] || clients[0] || {};
  return {
    found: true,
    source: "Hudson Rock Cavalier (Employee Stealer Logs)",
    employee_credentials_leaked: employees.length,
    client_credentials_leaked: clients.length,
    total_compromised_accounts: total,
    sample_computer_name: sample.computer_name || "Unknown",
    sample_os: sample.operating_system || "Unknown",
    sample_date_compromised: sample.date_compromised || "Unknown",
    note: `${employees.length} employee + ${clients.length} client credential sets found via infostealer malware`,
  };
}

// Grep.app — public GitHub repos search for leaked credentials/code/config files
async function fromGrepApp(query: string): Promise<SourceResult> {
  const d = await api(
    `https://grep.app/api/search?q=${encodeURIComponent(query)}&case=false&regexp=false`,
    {}, 12000
  );
  if (!d?.hits?.hits?.length) return { found: false, source: "Grep.app (Public Code Leak Search)" };
  const hits = d.hits.hits.slice(0, 10);
  const total = d.hits.total?.value || hits.length;
  const repos = [...new Set(hits.map((h: any) => h._source?.repo?.raw || ""))].filter(Boolean).slice(0, 6).join(", ");
  const files = hits.slice(0, 4).map((h: any) => h._source?.path?.raw || "").filter(Boolean).join(", ");
  const languages = [...new Set(hits.map((h: any) => h._source?.lang?.raw || ""))].filter(Boolean).join(", ");
  return {
    found: total > 0,
    source: "Grep.app (Public Code Repositories)",
    code_results_found: total,
    repositories: repos || "See grep.app",
    sample_files: files || "Various",
    languages_detected: languages || "Unknown",
    search_link: `https://grep.app/search?q=${encodeURIComponent(query)}`,
    note: `"${query}" found in ${total} public GitHub repository file(s) — check for leaked credentials, secrets, or config`,
  };
}

// ── CIRCL HASHLOOKUP (hashes → known-good file detection) ────────────────────
async function fromCIRCLHash(hash: string, algo: "sha256" | "md5" | "sha1"): Promise<SourceResult> {
  const endpoint = algo === "sha256" ? "sha-256" : algo === "sha1" ? "sha-1" : "md5";
  const d = await api(`https://hashlookup.circl.lu/lookup/${endpoint}/${hash}`, {}, 10000);
  if (!d || d["message"]) return { found: false, source: "CIRCL HASHLOOKUP" };
  // CIRCL finds it → the file is KNOWN-GOOD (in NSRL/trusted corpus)
  return {
    found: true,
    known_clean: true,
    source: "CIRCL HASHLOOKUP",
    file_name: d.FileName, file_size: d.FileSize,
    product: d.ProductName, os: d.OpSystemCode,
    note: "⚠️ File found in known-good corpus — likely NOT malware (NSRL/trusted)",
  };
}

