// ── Spamhaus ZEN DNSBL (via DNS-over-HTTPS) ──────────────────────────────────
async function fromSpamhaus(ip: string): Promise<SourceResult> {
  const reversed = ip.split(".").reverse().join(".");
  const d = await api(`https://dns.google/resolve?name=${reversed}.zen.spamhaus.org&type=A`, {}, 8000);
  if (!d?.Answer?.length) return { found: false, source: "Spamhaus ZEN DNSBL" };
  const listed = (d.Answer as any[]).some((a: any) => String(a.data).startsWith("127.0.0."));
  if (!listed) return { found: false, source: "Spamhaus ZEN DNSBL" };
  const codes = (d.Answer as any[]).map((a: any) => a.data).filter((v: string) => v.startsWith("127.0.0."));
  const meanings = codes.map((c: string) => {
    const n = c.split(".").pop();
    if (n === "2") return "SBL (Spam source)";
    if (n === "3") return "CSS (Snowshoe spam)";
    if (n === "4" || n === "5" || n === "6" || n === "7") return "XBL (Exploits/Zombies/Malware)";
    if (n === "9") return "SBL CSS";
    if (n === "10" || n === "11") return "PBL (Policy block — dynamic IP)";
    return `Return code ${n}`;
  });
  return {
    found: true,
    source: "Spamhaus ZEN DNSBL",
    listed_in: meanings.join(", "),
    return_codes: codes.join(", "),
    note: `Listed in Spamhaus ZEN: ${meanings.join(", ")}`,
  };
}

