// ── CISA Known Exploited Vulnerabilities (standalone CVE check) ───────────────
// In-memory cache so the ~300 KB JSON is only downloaded once per session
let _kevCache: { vulnerabilities: any[] } | null = null;
let _kevCacheTime = 0;
const KEV_TTL = 3_600_000; // 1 hour

const KEV_URLS = [
  "https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json",
  "https://corsproxy.io/?" + encodeURIComponent("https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json"),
  "https://raw.githubusercontent.com/cisagov/known-exploited-vulnerabilities/main/known_exploited_vulnerabilities.json",
  "https://api.allorigins.win/raw?url=" + encodeURIComponent("https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json"),
];

async function fetchKEVCatalog(): Promise<{ vulnerabilities: any[] } | null> {
  if (_kevCache && Date.now() - _kevCacheTime < KEV_TTL) return _kevCache;
  for (const url of KEV_URLS) {
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), 20000);
      const res = await fetch(url, { signal: ctrl.signal, headers: { Accept: "application/json" } });
      clearTimeout(t);
      if (!res.ok) continue;
      const data = await res.json();
      if (data?.vulnerabilities?.length) {
        _kevCache = data;
        _kevCacheTime = Date.now();
        return data;
      }
    } catch { /* try next URL */ }
  }
  return null;
}

async function fromCISAKEV(cveId: string): Promise<SourceResult> {
  try {
    const d = await fetchKEVCatalog();
    if (!d?.vulnerabilities?.length) return { found: false, source: "CISA KEV", note: "Catalog temporarily unavailable" };
    const hit = (d.vulnerabilities as any[]).find((v: any) =>
      v.cveID?.toLowerCase() === cveId.toLowerCase()
    );
    if (!hit) return { found: false, source: "CISA KEV", note: "Not on CISA Known Exploited Vulnerabilities list" };
    return {
      found: true,
      source: "CISA Known Exploited Vulnerabilities",
      vendor: hit.vendorProject,
      product: hit.product,
      vulnerability_name: hit.vulnerabilityName,
      date_added: hit.dateAdded,
      due_date: hit.dueDate,
      required_action: hit.requiredAction,
      short_description: hit.shortDescription,
      note: `ACTIVELY EXPLOITED — on CISA KEV since ${hit.dateAdded}. Federal agencies must patch by ${hit.dueDate}.`,
    };
  } catch {
    return { found: false, source: "CISA KEV", note: "Catalog temporarily unavailable" };
  }
}

