// ── URLScan.io submit + search (domains/URLs — look for malicious verdicts) ───
async function fromBinaryEdgeDomain(domain: string): Promise<SourceResult> {
  // Use crt.sh to check for suspicious certificate issuance patterns
  const d = await api(`https://crt.sh/?q=${encodeURIComponent(domain)}&output=json`, {}, 12000);
  if (!Array.isArray(d) || !d.length) return { found: false, source: "Certificate Transparency" };
  const recent = d.filter((c: any) => {
    const issued = new Date(c.not_before || 0).getTime();
    return (Date.now() - issued) < 90 * 24 * 60 * 60 * 1000; // last 90 days
  });
  const issuers = [...new Set(d.slice(0, 20).map((c: any) => c.issuer_name || "").filter(Boolean))];
  const names = [...new Set(d.slice(0, 10).map((c: any) => c.common_name || "").filter(Boolean))];
  return {
    found: false, // informational only — not a malicious signal by itself
    source: "Certificate Transparency (crt.sh)",
    total_certs: d.length,
    recent_90d: recent.length,
    issuers: issuers.slice(0, 3).join("; "),
    common_names: names.slice(0, 5).join(", "),
    note: `${d.length} certificates found (${recent.length} issued in last 90 days)`,
  };
}

async function fromInternalDB(value: string, type: ObsType): Promise<{ hits: any[] }> {
  let q = supabase.from("threat_items").select("id,title,severity,published_at,source_name,link,excerpt").limit(8);
  if (type === "ip") q = q.contains("iocs", { ipv4: [value] });
  else if (type === "sha256") q = q.contains("iocs", { sha256: [value] });
  else if (type === "md5") q = q.or(`title.ilike.%${value}%,excerpt.ilike.%${value}%`);
  else if (type === "sha1") q = q.or(`title.ilike.%${value}%,excerpt.ilike.%${value}%`);
  else if (type === "cve") q = q.contains("iocs", { cves: [value.toUpperCase()] });
  else if (type === "domain" || type === "url") {
    const host = value.replace(/^https?:\/\//, "").split("/")[0];
    q = q.or(`title.ilike.%${host}%,excerpt.ilike.%${host}%`);
  }
  else q = q.or(`title.ilike.%${value}%,excerpt.ilike.%${value}%`);
  const { data } = await q;
  return { hits: data || [] };
}

// ── Weighted threat scoring ────────────────────────────────────────────────────
// Each source has a weight. Score >= 70 → malicious, >= 30 → suspicious, else clean.
// Known-good signals (CIRCL, GreyNoise riot) REDUCE the score.
function computeWeightedVerdict(results: Record<string, SourceResult>, type: ObsType): { verdict: Verdict; score: number; positives: number } {
  let score = 0;
  let positives = 0;

  const r = results;

  // ── Tier 0: VirusTotal — 70+ AV engines, most comprehensive source ────────────
  if (r.virustotal?.found) {
    positives++;
    const mal = r.virustotal.malicious_engines || 0;
    const sus = r.virustotal.suspicious_engines || 0;
    if (mal >= 10) score += 90;        // 10+ engines = definitive malicious
    else if (mal >= 5) score += 75;    // 5-9 engines = very likely malicious
    else if (mal >= 2) score += 60;    // 2-4 engines = probable malicious
    else if (mal >= 1) score += 45;    // 1 engine = suspicious
    else if (sus >= 3) score += 40;
    else if (sus >= 1) score += 25;
  }

  // ── Tier 1: Definitive malicious sources (55pts each — single hit = malicious) ──
  if (r.threatfox?.found)     { score += 55; positives++; }
  if (r.malwarebazaar?.found) { score += 55; positives++; }
  if (r.feodo?.found)         { score += 55; positives++; }
  if (r.abusessl?.found)      { score += 55; positives++; }   // AbuseCH SSL blocklist — confirmed C2

  // ── Tier 2: High-confidence blocklists & scan data ────────────────────────────
  // URLhaus — distinguish active vs inactive
  if (r.urlhaus?.found) {
    positives++;
    score += r.urlhaus.url_status === "online" ? 50 : 25;
  }

  // Spamhaus ZEN — highly reliable DNSBL
  if (r.spamhaus?.found) {
    positives++;
    const listing = r.spamhaus.listed_in || "";
    // SBL/XBL are more serious than PBL (which blocks dynamic IPs)
    score += listing.includes("SBL") || listing.includes("XBL") ? 50 : 25;
  }

  // CISA KEV (standalone) — actively exploited, highest severity
  if (r.cisakev?.found) { score += 65; positives++; }

  // PhishTank — confirmed phishing
  if (r.phishtank?.found) { score += 60; positives++; }

  // SANS ISC DShield — attack reports
  if (r.dshield?.found) {
    positives++;
    const attacks = r.dshield.attacks || 0;
    score += attacks > 100 ? 45 : attacks > 10 ? 35 : 25;
  }

  // ── Tier 3: Intelligence platforms ────────────────────────────────────────────
  // AlienVault OTX — weighted by pulse count
  if (r.otx?.found) {
    positives++;
    const pulses = r.otx.pulse_count || 1;
    score += Math.min(45, 15 + pulses * 3);
  }

  // AbuseIPDB — score-based
  if (r.abuseipdb?.found) {
    positives++;
    const pct = parseInt(String(r.abuseipdb.abuse_score || "0"), 10);
    score += pct > 80 ? 50 : pct > 50 ? 35 : 20;
  }

  // Emerging Threats blocklist
  if (r.emerging?.found) { score += 40; positives++; }

  // StopForumSpam
  if (r.stopforumspam?.found) {
    positives++;
    const freq = r.stopforumspam.frequency || 1;
    score += freq > 100 ? 35 : freq > 10 ? 25 : 15;
  }

  // GreyNoise — malicious classification OR active noise/scanner
  if (r.greynoise?.found) {
    positives++;
    const cls = r.greynoise.classification || "";
    score += cls === "malicious" ? 40 : 20; // noise/scanner IPs get 20pts
  }
  // GreyNoise RIOT = known benign infrastructure — REDUCE score significantly
  if (r.greynoise?.riot_benign) score -= 35;

  // URLScan
  if (r.urlscan?.found) {
    positives++;
    const malCount = r.urlscan.malicious_scans || 1;
    score += Math.min(40, 15 + malCount * 5);
  }

  // Pulsedive — risk-based
  if (r.pulsedive?.found) {
    positives++;
    const risk = (r.pulsedive.risk || "").toLowerCase();
    score += risk === "critical" ? 40 : risk === "high" ? 30 : risk === "medium" ? 15 : 8;
  }

  // ── Tier 4: Contextual / benign signals ───────────────────────────────────────
  // CIRCL HASHLOOKUP — found means KNOWN-CLEAN file, penalize score heavily
  if (r.circl?.found && r.circl?.known_clean) score -= 50;

  // Shodan — informational only, slight positive if vulns listed
  if (r.shodan?.found && r.shodan?.vulns) score += 5;

  // EPSS for CVEs — high exploitation probability is a signal
  if (type === "cve" && r.epss?.found) {
    const epss = r.epss.epss_score || 0;
    if (epss > 0.7) { score += 35; positives++; }
    else if (epss > 0.3) { score += 15; }
  }

  // Domain / keyword breach scoring
  if (type === "domain" || type === "keyword") {
    const hibpSrc = r.hibpdomain || r.hibp;
    if (hibpSrc?.found) {
      positives++;
      const hasPasswords = String(hibpSrc.passwords_exposed || "").includes("YES");
      const hasSourceCode = String(hibpSrc.source_code_exposed || "").includes("YES");
      const count = Number(hibpSrc.breach_count) || 1;
      score += hasSourceCode ? 70 : hasPasswords ? 55 : 35;
      if (count >= 3) score += 10;
    }
    if (r.hibp?.found && type === "keyword") {
      positives++;
      const hasPasswords = String(r.hibp.passwords_exposed || "").includes("YES");
      score += hasPasswords ? 50 : 30;
    }
    if (r.hudsonrock?.found) { score += 65; positives++; }
    if (r.grepapp?.found) { score += 25; positives++; }
  }

  // Email-specific scoring
  if (type === "email") {
    if (r.hudsonrock?.found) { score += 75; positives++; }
    if (r.hibp?.found) {
      positives++;
      const hasPasswords = String(r.hibp.passwords_exposed || "").includes("YES");
      const breachCount = Number(r.hibp.breach_count) || 1;
      score += hasPasswords ? 65 : 45;
      if (breachCount >= 5) score += 10;
    }
    if (r.emailrep?.found) {
      positives++;
      if (r.emailrep.credentials_leaked === "YES") score += 40;
      else if (r.emailrep.data_breach === "YES") score += 25;
      else if (r.emailrep.malicious_activity === "YES") score += 30;
      else score += 10;
    }
  }

  // CISA KEV from NVD — actively exploited CVE
  if (type === "cve" && r.nvd?.cisa_kev) { score += 50; positives++; }

  // Standalone CISA KEV check
  if (type === "cve" && r.cisakev?.found) { score += 65; positives++; }

  // CVSS score boost — critical/high severity CVEs
  if (type === "cve" && r.nvd?.cvss_score) {
    const cvss = parseFloat(String(r.nvd.cvss_score));
    if (cvss >= 9.0) score += 20;
    else if (cvss >= 7.0) score += 10;
  }

  // ── Hard floors: confirmed malicious sources guarantee MALICIOUS verdict ─────
  if (r.threatfox?.found || r.malwarebazaar?.found || r.feodo?.found || r.abusessl?.found) {
    score = Math.max(score, 70);
  }
  if (r.spamhaus?.found && String(r.spamhaus.listed_in || "").match(/SBL|XBL/)) {
    score = Math.max(score, 70);
  }
  if (r.cisakev?.found || r.phishtank?.found) {
    score = Math.max(score, 70);
  }
  // VirusTotal ≥5 engines is a hard malicious floor
  if ((r.virustotal?.malicious_engines || 0) >= 5) {
    score = Math.max(score, 70);
  }

  score = Math.max(0, score);

  // ── Verdict ─────────────────────────────────────────────────────────────────
  // CRITICAL: "clean" means actively verified safe, NOT just "not found".
  // If zero sources flagged this IOC, we have no evidence either way → UNKNOWN.
  let verdict: Verdict;
  if (score >= 70) {
    verdict = "malicious";
  } else if (score >= 30) {
    verdict = "suspicious";
  } else if (positives === 0 && !r.circl?.known_clean && !r.greynoise?.riot_benign) {
    // No source has any data on this IOC — absence of evidence ≠ evidence of safety
    verdict = "unknown";
  } else {
    verdict = "clean";
  }

  return { verdict, score, positives };
}

// ── Enrich orchestrator ───────────────────────────────────────────────────────
async function enrich(value: string, type: ObsType, onProgress: (n: number) => void): Promise<EnrichResult & { score: number }> {
  const results: Record<string, SourceResult> = {};
  const tasks: Array<[string, Promise<SourceResult>]> = [];

  if (type === "ip") {
    tasks.push(["threatfox",      fromThreatFox(value, type)]);
    tasks.push(["urlhaus",        fromURLhaus(value, type)]);
    tasks.push(["feodo",          fromFeodo(value)]);
    tasks.push(["greynoise",      fromGreyNoise(value)]);
    tasks.push(["shodan",         fromShodan(value)]);
    tasks.push(["pulsedive",      fromPulsedive(value)]);
    tasks.push(["otx",            fromOTX(value, type)]);
    tasks.push(["abuseipdb",      fromAbuseIPDB(value)]);
    tasks.push(["virustotal",     fromVirusTotal(value, type)]);
    tasks.push(["emerging",       fromEmergingThreats(value)]);
    tasks.push(["urlscan",        fromURLScan(value, type)]);
    tasks.push(["dshield",        fromDShield(value)]);
    tasks.push(["spamhaus",       fromSpamhaus(value)]);
    tasks.push(["stopforumspam",  fromStopForumSpam(value)]);
    tasks.push(["abusessl",       fromAbuseCHSSL(value)]);
  } else if (type === "domain") {
    tasks.push(["threatfox",    fromThreatFox(value, type)]);
    tasks.push(["urlhaus",      fromURLhaus(value, type)]);
    tasks.push(["pulsedive",    fromPulsedive(value)]);
    tasks.push(["otx",          fromOTX(value, type)]);
    tasks.push(["urlscan",      fromURLScan(value, type)]);
    tasks.push(["virustotal",   fromVirusTotal(value, type)]);
    tasks.push(["phishtank",    fromPhishTank(value)]);
    tasks.push(["certsh",       fromBinaryEdgeDomain(value)]);
    // Breach intelligence for domains
    tasks.push(["hibpdomain",   fromHIBPDomain(value)]);
    tasks.push(["hudsonrock",   fromHudsonRockDomain(value)]);
    tasks.push(["grepapp",      fromGrepApp(value)]);
  } else if (type === "keyword") {
    const guessedDomain = guessDomain(value);
    tasks.push(["hibp",         fromHIBPKeyword(value)]);
    tasks.push(["hibpdomain",   fromHIBPDomain(guessedDomain)]);
    tasks.push(["hudsonrock",   fromHudsonRockDomain(guessedDomain)]);
    tasks.push(["grepapp",      fromGrepApp(value)]);
    tasks.push(["pulsedive",    fromPulsedive(value)]);
  } else if (type === "url") {
    tasks.push(["urlhaus",    fromURLhaus(value, type)]);
    tasks.push(["threatfox",  fromThreatFox(value, type)]);
    tasks.push(["pulsedive",  fromPulsedive(value)]);
    tasks.push(["urlscan",    fromURLScan(value, type)]);
    tasks.push(["otx",        fromOTX(value, type)]);
    tasks.push(["phishtank",    fromPhishTank(value)]);
    tasks.push(["virustotal",   fromVirusTotal(value, type)]);
  } else if (type === "sha256" || type === "md5" || type === "sha1") {
    tasks.push(["threatfox",     fromThreatFox(value, type)]);
    tasks.push(["malwarebazaar", fromMalwareBazaar(value)]);
    tasks.push(["pulsedive",     fromPulsedive(value)]);
    tasks.push(["otx",           fromOTX(value, type)]);
    tasks.push(["virustotal",    fromVirusTotal(value, type)]);
    tasks.push(["circl",         fromCIRCLHash(value, type as "sha256" | "md5" | "sha1")]);
  } else if (type === "cve") {
    tasks.push(["nvd",       fromNVD(value.toUpperCase())]);
    tasks.push(["epss",      fromEPSS(value.toUpperCase())]);
    tasks.push(["threatfox", fromThreatFox(value, type)]);
    tasks.push(["osv",       fromOSV(value)]);
    tasks.push(["cisakev",   fromCISAKEV(value.toUpperCase())]);
  } else if (type === "email") {
    tasks.push(["hibp",       fromHIBP(value)]);
    tasks.push(["emailrep",   fromEmailRep(value)]);
    tasks.push(["hudsonrock", fromHudsonRock(value)]);
  } else {
    tasks.push(["osv",       fromOSV(value)]);
    tasks.push(["pulsedive", fromPulsedive(value)]);
    tasks.push(["otx",       fromOTX(value, type)]);
  }

  let done = 0;
  await Promise.all(tasks.map(async ([name, p]) => {
    try { results[name] = await p; } catch { results[name] = { found: false, source: name, error: "timeout" }; }
    done++;
    onProgress(Math.round((done / (tasks.length + 1)) * 90));
  }));

  const [{ hits: internalHits }] = await Promise.all([fromInternalDB(value, type)]);

  const { verdict, score, positives } = computeWeightedVerdict(results, type);

  return { value, type, verdict, positives, total: tasks.length, results, internalHits, score };
}

