// ── IOC AI CTI Report Panel ───────────────────────────────────────────────────
const CTI_HDRS = ["EXECUTIVE SUMMARY","IOC DETAILS","THREAT ACTOR / MALWARE ASSOCIATION",
  "SUSPICIOUS INDICATORS","INDICATORS OF COMPROMISE","ATTACK CONTEXT",
  "TACTICS, TECHNIQUES & PROCEDURES (MITRE ATT&CK)","RECOMMENDATIONS / MITIGATION","ANALYST CONCLUSION"];

function IOCAIReport({ result }: { result: EnrichResult }) {
  const { toast } = useToast();
  const [report, setReport]     = useState("");
  const [loading, setLoading]   = useState(true);
  const [msg, setMsg]           = useState("Generating CTI report…");
  const [sending, setSending]   = useState(false);
  const [sent, setSent]         = useState(false);

  useEffect(() => {
    const t1 = setTimeout(()=>setMsg(GROQ_KEY ? "Calling Groq AI (Llama 70B)…" : "Calling local Ollama model…"),2000);
    const t2 = setTimeout(()=>setMsg("Building report from enrichment data…"),15000);
    generateIOCReport(result).then(r => {
      clearTimeout(t1); clearTimeout(t2);
      setReport(r); setLoading(false);
    });
    return ()=>{clearTimeout(t1);clearTimeout(t2);};
  }, [result.value]);

  async function handleEmailReport() {
    if (!report) return;
    setSending(true);
    try {
      const cves = (result.results.nvd as any)?.cve_id ? [(result.results.nvd as any).cve_id] : [];
      const ips  = result.type === "ip" ? [result.value] : [];
      const { error } = await supabase.functions.invoke("send-alerts", {
        body: {
          manual_item: {
            id: `ioc-${result.value}`,
            title: `IOC Report: ${result.value} [${result.type.toUpperCase()} · ${result.verdict.toUpperCase()}]`,
            link: "",
            excerpt: report.slice(0, 600),
            severity: result.verdict === "malicious" ? "critical" : result.verdict === "suspicious" ? "high" : "medium",
            category: "IOC Analysis",
            source_name: "ThreatLens IOC Lookup",
            published_at: new Date().toISOString(),
            iocs: { cves, ipv4: ips },
          },
          manual_summary: report,
        },
      });
      if (error) throw error;
      setSent(true);
      toast({ title: "Report emailed", description: "IOC threat intelligence report sent to your alert email." });
      setTimeout(() => setSent(false), 5000);
    } catch (e: any) {
      toast({ title: "Email failed", description: e.message || "Check SMTP settings in Supabase secrets (SMTP_HOST, SMTP_USER, SMTP_PASS, ALERT_EMAIL).", variant: "destructive" });
    } finally { setSending(false); }
  }

  if (loading) return (
    <div className="flex items-center gap-2 py-6 text-sm text-muted-foreground">
      <RefreshCw className="h-4 w-4 animate-spin text-primary" />{msg}
    </div>
  );

  // Parse sections
  const found: {title:string;pos:number}[] = [];
  for (const h of CTI_HDRS) { const i=report.indexOf(h); if(i!==-1) found.push({title:h,pos:i}); }
  found.sort((a,b)=>a.pos-b.pos);
  const sections = found.map(({title,pos},i)=>({
    title, body: report.slice(pos+title.length, found[i+1]?.pos ?? pos+title.length+2000).replace(/^[::\n\s]+/,"").trim()
  })).filter(s=>s.body);

  const sStyle = (t:string) => {
    if (t.includes("SUSPICIOUS")) return { bg:"bg-red-500/5",   lbl:"text-red-400",    icon:"⚠️" };
    if (t.includes("ATTACK"))    return { bg:"bg-orange-400/5", lbl:"text-orange-400", icon:"⛓" };
    if (t.includes("INDICATORS OF")) return { bg:"bg-yellow-400/5",lbl:"text-yellow-400",icon:"🔍" };
    if (t.includes("TACTICS"))   return { bg:"bg-purple-400/5", lbl:"text-purple-400", icon:"🎯" };
    if (t.includes("RECOMMEND")) return { bg:"bg-green-500/5",  lbl:"text-green-400",  icon:"🚨" };
    if (t.includes("EXECUTIVE")) return { bg:"bg-primary/5",    lbl:"text-primary",    icon:"📋" };
    return { bg:"", lbl:"text-muted-foreground", icon:"▸" };
  };

  return (
    <div className="space-y-3">
      {/* Email button */}
      <div className="flex items-center justify-between">
        <span className="text-xs text-muted-foreground">
          {GROQ_KEY ? "Generated by Groq AI (Llama 70B)" : "Generated by local model"}
        </span>
        <Button
          size="sm" variant="outline"
          className="h-7 text-xs gap-1.5"
          onClick={handleEmailReport}
          disabled={sending || sent}
        >
          {sent ? <Check className="h-3 w-3 text-success" /> : sending ? <RefreshCw className="h-3 w-3 animate-spin" /> : <Mail className="h-3 w-3" />}
          {sent ? "Sent!" : sending ? "Sending…" : "Email Report"}
        </Button>
      </div>

      <div className="divide-y divide-border/30 rounded-lg border border-border/40 overflow-hidden">
        {sections.map((s,i)=>{
          const st = sStyle(s.title);
          return (
            <div key={i} className={`px-4 py-3 ${st.bg}`}>
              <div className={`text-[10px] font-bold uppercase tracking-widest mb-2 ${st.lbl}`}>
                {st.icon} {s.title}
              </div>
              <div className="text-sm text-foreground/90 leading-relaxed whitespace-pre-wrap">{s.body}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Case Management Tab ──────────────────────────────────────────────────────
type CaseStatus = "open" | "investigating" | "resolved" | "closed";
type InvestigationCase = {
  id: string; title: string; description: string;
  status: CaseStatus; severity: string;
  iocs: string[]; notes: string;
  created_at: string; updated_at: string;
};

const STATUS_BADGE: Record<CaseStatus, string> = {
  open:          "bg-destructive/15 text-destructive border-destructive/40",
  investigating: "bg-orange-400/15 text-orange-400 border-orange-400/40",
  resolved:      "bg-green-500/15 text-green-400 border-green-500/40",
  closed:        "bg-muted text-muted-foreground border-muted",
};

function CaseManagementTab() {
  const { toast } = useToast();
  const [cases, setCases] = useState<InvestigationCase[]>([]);
  const [loadingCases, setLoadingCases] = useState(true);
  const [selected, setSelected] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newDesc, setNewDesc] = useState("");
  const [newSev, setNewSev] = useState("high");
  const [addIocInput, setAddIocInput] = useState("");

  useEffect(() => {
    supabase.from("cases")
      .select("id,title,description,severity,status,iocs,notes,created_at,updated_at")
      .in("status", ["open","investigating","resolved","closed"])
      .order("created_at", { ascending: false })
      .limit(100)
      .then(({ data }) => {
        setCases((data ?? []) as unknown as InvestigationCase[]);
        setLoadingCases(false);
      });
  }, []);

  async function createCase() {
    if (!newTitle.trim()) return;
    const row = { title: newTitle.trim(), description: newDesc.trim(), status: "open" as CaseStatus, severity: newSev, category: "IOC Investigation", iocs: [], notes: "" };
    const { data, error } = await supabase.from("cases").insert([row]).select().single();
    if (error) { toast({ title: "Create failed", description: error.message, variant: "destructive" }); return; }
    const c = data as unknown as InvestigationCase;
    setCases(prev => [c, ...prev]);
    setNewTitle(""); setNewDesc(""); setCreating(false);
    setSelected(c.id);
    toast({ title: "Case created", description: c.title });
  }

  async function deleteCase(id: string) {
    const { error } = await supabase.from("cases").delete().eq("id", id);
    if (error) { toast({ title: "Delete failed", description: error.message, variant: "destructive" }); return; }
    setCases(prev => prev.filter(c => c.id !== id));
    if (selected === id) setSelected(null);
  }

  async function updateCase(id: string, patch: Partial<InvestigationCase>) {
    const { error } = await supabase.from("cases").update({ ...patch, updated_at: new Date().toISOString() }).eq("id", id);
    if (error) { toast({ title: "Update failed", description: error.message, variant: "destructive" }); return; }
    setCases(prev => prev.map(c => c.id === id ? { ...c, ...patch, updated_at: new Date().toISOString() } : c));
  }

  async function addIOC(caseId: string, value: string) {
    if (!value.trim()) return;
    const c = cases.find(x => x.id === caseId);
    if (!c) return;
    const newIocs = [...(c.iocs ?? []), value.trim()];
    await updateCase(caseId, { iocs: newIocs });
    setAddIocInput("");
  }

  async function removeIOC(caseId: string, iocValue: string) {
    const c = cases.find(x => x.id === caseId);
    if (!c) return;
    await updateCase(caseId, { iocs: (c.iocs ?? []).filter(v => v !== iocValue) });
  }

  function exportCase(c: InvestigationCase) {
    const blob = new Blob([JSON.stringify(c, null, 2)], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `case-${c.title.replace(/\s+/g, "-").toLowerCase()}.json`;
    a.click();
    URL.revokeObjectURL(a.href);
  }

  const activeCase = cases.find(c => c.id === selected);

  const statCounts = {
    open: cases.filter(c => c.status === "open").length,
    investigating: cases.filter(c => c.status === "investigating").length,
    resolved: cases.filter(c => c.status === "resolved").length,
  };

  return (
    <div className="space-y-6">
      {/* Header + stats */}
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h2 className="text-lg font-bold flex items-center gap-2"><FolderOpen className="h-5 w-5 text-primary" /> Investigation Cases</h2>
          <p className="text-xs text-muted-foreground mt-0.5">Track IOC investigations, attach indicators, and add notes. Saved to Supabase.</p>
        </div>
        <div className="flex items-center gap-3 text-xs">
          <span className="text-destructive font-semibold">{statCounts.open} open</span>
          <span className="text-orange-400 font-semibold">{statCounts.investigating} active</span>
          <span className="text-green-400 font-semibold">{statCounts.resolved} resolved</span>
          <Button size="sm" onClick={() => setCreating(v => !v)} className="gap-1.5 h-8">
            <Plus className="h-3.5 w-3.5" /> New Case
          </Button>
        </div>
      </div>

      {/* New case form */}
      {creating && (
        <Card className="border-primary/30 bg-card/80">
          <CardContent className="pt-4 space-y-3">
            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="text-xs font-medium text-muted-foreground">Case Title *</label>
                <Input className="mt-1" placeholder="e.g. LockBit intrusion investigation" value={newTitle} onChange={e => setNewTitle(e.target.value)} />
              </div>
              <div>
                <label className="text-xs font-medium text-muted-foreground">Severity</label>
                <select className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={newSev} onChange={e => setNewSev(e.target.value)}>
                  <option value="critical">Critical</option>
                  <option value="high">High</option>
                  <option value="medium">Medium</option>
                  <option value="low">Low</option>
                </select>
              </div>
            </div>
            <div>
              <label className="text-xs font-medium text-muted-foreground">Description</label>
              <textarea className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm h-16 resize-none"
                placeholder="Brief description of the incident..." value={newDesc} onChange={e => setNewDesc(e.target.value)} />
            </div>
            <div className="flex gap-2">
              <Button onClick={createCase} disabled={!newTitle.trim()} className="h-8 text-xs">Create Case</Button>
              <Button variant="outline" onClick={() => setCreating(false)} className="h-8 text-xs">Cancel</Button>
            </div>
          </CardContent>
        </Card>
      )}

      {cases.length === 0 && !creating && (
        <div className="rounded-lg border border-border/40 bg-muted/10 py-16 text-center">
          <FolderOpen className="h-10 w-10 text-muted-foreground mx-auto mb-3" />
          <p className="text-sm font-medium">No cases yet</p>
          <p className="text-xs text-muted-foreground mt-1">Create a case to track an IOC investigation</p>
        </div>
      )}

      {/* Cases list + detail */}
      {cases.length > 0 && (
        <div className="grid gap-4 md:grid-cols-3">
          {/* Case list */}
          <div className="space-y-2">
            {cases.map(c => (
              <button key={c.id} onClick={() => setSelected(c.id === selected ? null : c.id)}
                className={`w-full text-left rounded-lg border p-3 transition-all hover:border-primary/40 ${selected === c.id ? "border-primary/60 bg-primary/5" : "border-border/50 bg-card/60"}`}>
                <div className="flex items-center gap-2 mb-1">
                  <Badge className={`border text-[9px] px-1.5 ${STATUS_BADGE[c.status]}`}>{c.status.toUpperCase()}</Badge>
                  <span className={`text-[9px] font-semibold ${c.severity === "critical" ? "text-destructive" : c.severity === "high" ? "text-orange-400" : "text-yellow-400"}`}>{c.severity.toUpperCase()}</span>
                </div>
                <p className="text-xs font-medium line-clamp-1">{c.title}</p>
                <div className="flex items-center gap-2 mt-1 text-[9px] text-muted-foreground">
                  <span>{c.iocs.length} IOC{c.iocs.length !== 1 ? "s" : ""}</span>
                  <span>·</span>
                  <span>{new Date(c.created_at).toLocaleDateString()}</span>
                </div>
              </button>
            ))}
          </div>

          {/* Case detail */}
          {activeCase ? (
            <div className="md:col-span-2 space-y-4">
              <Card className="border-border/60 bg-card/80">
                <CardHeader className="pb-2">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <CardTitle className="text-base">{activeCase.title}</CardTitle>
                      {activeCase.description && <p className="text-xs text-muted-foreground mt-1">{activeCase.description}</p>}
                    </div>
                    <div className="flex gap-1 shrink-0">
                      <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => exportCase(activeCase)}>
                        <Download className="h-3 w-3" /> Export
                      </Button>
                      <Button size="sm" variant="ghost" className="h-7 text-xs text-destructive hover:text-destructive"
                        onClick={() => { if (confirm("Delete this case?")) deleteCase(activeCase.id); }}>
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {/* Status + severity */}
                  <div className="flex gap-3 flex-wrap">
                    <div>
                      <label className="text-[10px] text-muted-foreground uppercase tracking-wide">Status</label>
                      <select className="mt-1 block rounded border border-input bg-background px-2 py-1 text-xs"
                        value={activeCase.status}
                        onChange={e => updateCase(activeCase.id, { status: e.target.value as CaseStatus })}>
                        <option value="open">Open</option>
                        <option value="investigating">Investigating</option>
                        <option value="resolved">Resolved</option>
                        <option value="closed">Closed</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] text-muted-foreground uppercase tracking-wide">Severity</label>
                      <select className="mt-1 block rounded border border-input bg-background px-2 py-1 text-xs"
                        value={activeCase.severity}
                        onChange={e => updateCase(activeCase.id, { severity: e.target.value })}>
                        <option value="critical">Critical</option>
                        <option value="high">High</option>
                        <option value="medium">Medium</option>
                        <option value="low">Low</option>
                      </select>
                    </div>
                    <div className="ml-auto text-[10px] text-muted-foreground self-end">
                      Updated {new Date(activeCase.updated_at).toLocaleString()}
                    </div>
                  </div>

                  {/* IOCs */}
                  <div>
                    <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2 flex items-center gap-2">
                      <Tag className="h-3 w-3" /> Indicators of Compromise ({activeCase.iocs.length})
                    </div>
                    <div className="flex gap-2 mb-2">
                      <Input className="h-8 text-xs font-mono flex-1" placeholder="IP, domain, hash, URL, CVE…"
                        value={addIocInput} onChange={e => setAddIocInput(e.target.value)}
                        onKeyDown={e => e.key === "Enter" && addIOC(activeCase.id, addIocInput)} />
                      <Button size="sm" className="h-8 text-xs" onClick={() => addIOC(activeCase.id, addIocInput)}>Add IOC</Button>
                    </div>
                    {activeCase.iocs.length > 0 ? (
                      <div className="space-y-1 max-h-48 overflow-y-auto">
                        {activeCase.iocs.map(ioc => (
                          <div key={ioc} className="flex items-center gap-2 rounded border border-border/40 bg-muted/20 px-2.5 py-1.5">
                            <span className="font-mono text-xs flex-1 truncate">{ioc}</span>
                            <a href={`/lookup?value=${encodeURIComponent(ioc)}`}
                              className="text-[9px] text-primary hover:underline shrink-0">Lookup</a>
                            <button onClick={() => removeIOC(activeCase.id, ioc)}
                              className="text-muted-foreground hover:text-destructive text-xs shrink-0">✕</button>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-xs text-muted-foreground py-2">No IOCs attached yet.</p>
                    )}
                  </div>

                  {/* Notes */}
                  <div>
                    <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1 flex items-center gap-2">
                      <FileText className="h-3 w-3" /> Notes
                    </div>
                    <textarea
                      className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm h-28 resize-none"
                      placeholder="Investigation notes, timeline, analyst findings…"
                      value={activeCase.notes}
                      onChange={e => updateCase(activeCase.id, { notes: e.target.value })}
                    />
                  </div>
                </CardContent>
              </Card>
            </div>
          ) : (
            <div className="md:col-span-2 rounded-lg border border-border/40 bg-muted/10 flex items-center justify-center h-48 text-muted-foreground text-sm">
              Select a case to view details
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ── Send IOC report via email (calls send-alerts edge function) ───────────────
async function sendIOCReportEmail(
  result: EnrichResult,
  brief: string,
  toast: (opts: any) => void,
  setSending: (v: boolean) => void,
) {
  setSending(true);
  try {
    const cves  = (result.results.nvd as any)?.cve_id ? [(result.results.nvd as any).cve_id] : [];
    const ips   = result.type === "ip" ? [result.value] : [];
    const today = new Date().toISOString();

    // Build a fake threat_item from enrichment result so send-alerts can use it
    const fakeItem = {
      id: `ioc-${result.value}`,
      title: `IOC Report: ${result.value} [${result.type.toUpperCase()} · ${result.verdict.toUpperCase()}]`,
      link: "",
      excerpt: brief.slice(0, 600),
      severity: result.verdict === "malicious" ? "critical" : result.verdict === "suspicious" ? "high" : "medium",
      category: "IOC Analysis",
      source_name: "ThreatLens IOC Lookup",
      published_at: today,
      iocs: { cves, ipv4: ips },
    };

    const { data, error } = await supabase.functions.invoke("send-alerts", {
      body: { manual_item: fakeItem, manual_summary: brief },
    });

    if (error) throw error;
    toast({ title: "Report emailed", description: "IOC threat intelligence report sent to your configured alert email." });
  } catch (e: any) {
    toast({ title: "Email failed", description: e.message || "Could not send email. Check SMTP settings in Supabase secrets.", variant: "destructive" });
  } finally {
    setSending(false);
  }
}

export default function IOCLookup() {
  const { toast } = useToast();
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const [query, setQuery] = useState(params.get("value") || "");
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<EnrichResult | null>(null);
  const [lastChecked, setLastChecked] = useState<Date | null>(null);
  const [emailSending, setEmailSending] = useState(false);
  const [aiBrief, setAiBrief] = useState("");
  const [history, setHistory] = useState<string[]>(() => {
    try { return JSON.parse(localStorage.getItem("ioc_history") || "[]"); } catch { return []; }
  });
  const inputRef = useRef<HTMLInputElement>(null);

  const run = useCallback(async (val?: string) => {
    const v = (val ?? query).trim();
    if (!v) { inputRef.current?.focus(); return; }
    const type = detectType(v);
    if (type === "unknown") {
      toast({ title: "Unrecognized observable", description: "Enter an IP, domain, URL, hash, CVE ID, email, or company/keyword name", variant: "destructive" });
      return;
    }
    setLoading(true); setResult(null); setProgress(5);
    setHistory(h => { const next = [v, ...h.filter(x => x !== v)].slice(0, 15); localStorage.setItem("ioc_history", JSON.stringify(next)); return next; });

    try {
      // Fire server-side enrichment (cached, uses server API keys) + browser enrichment in parallel
      const { data: { session } } = await supabase.auth.getSession();
      const supabaseUrl = (supabase as any).supabaseUrl as string;

      const [browserResult, serverResult] = await Promise.allSettled([
        enrich(v, type, p => setProgress(Math.min(p, 75))),
        fetch(`${supabaseUrl}/functions/v1/enrich-ioc?value=${encodeURIComponent(v)}`, {
          headers: { "Authorization": `Bearer ${session?.access_token ?? ""}` },
        }).then(r => r.ok ? r.json() : null).catch(() => null),
      ]);

      const r = browserResult.status === "fulfilled" ? browserResult.value : { value: v, type, verdict: "unknown" as const, positives: 0, total: 0, results: {}, internalHits: [], score: 0 };

      // Merge server-side enrichment into results (GeoIP, AbuseIPDB, RDAP, cached verdict)
      if (serverResult.status === "fulfilled" && serverResult.value?.results) {
        const srv = serverResult.value;
        // Add server-sourced results that browser may not have
        if (srv.results.abuseipdb?.found) r.results.abuseipdb = { ...srv.results.abuseipdb, source: "AbuseIPDB (server)" };
        if (srv.results.geoip?.found)     r.results.geoip     = { ...srv.results.geoip,     source: "GeoIP (server)" };
        if (srv.results.rdap?.found)      r.results.rdap      = { ...srv.results.rdap,       source: "RDAP/WHOIS (server)" };
        if (srv.results.otx?.found)       r.results.otx_srv   = { ...srv.results.otx,        source: "OTX (server)" };
        // If server says malicious and browser doesn't, trust server (it has more sources)
        if (srv.verdict === "malicious" && r.verdict !== "malicious") {
          r.verdict = "malicious";
          r.positives = Math.max(r.positives, srv.positive_sources);
        }
      }

      setResult(r);
      setLastChecked(new Date());
      setProgress(100);
      setTimeout(() => setProgress(0), 800);
    } catch (e: any) {
      toast({ title: "Enrichment failed", description: e.message, variant: "destructive" });
    } finally { setLoading(false); }
  }, [query, toast]);

  // Auto-run if navigated with ?value=
  useEffect(() => { const v = params.get("value"); if (v) run(v); }, []); // eslint-disable-line

  const verdict = result ? verdictCfg[result.verdict] : null;
  const TypeIcon = result ? (TYPE_ICON[result.type] || Search) : Search;
  const links = result ? (QUICK_LINKS[result.type]?.(result.value) || []) : [];

  return (
    <div className="container mx-auto px-4 py-8 max-w-5xl">

      {/* Header */}
      <div className="mb-6">
        <h1 className="text-3xl font-bold tracking-tight mb-1">IOC Lookup</h1>
        <p className="text-sm text-muted-foreground max-w-2xl mb-3">
          Enrich any observable across 15+ sources — ThreatFox, VirusTotal, AbuseIPDB, OTX,
          Spamhaus, DShield, GreyNoise, Shodan, Feodo, URLhaus, MalwareBazaar and more — all in parallel.
        </p>

        {/* API key status — shows immediately if keys are loaded */}
        <div className="flex flex-wrap gap-2 mb-1">
          {[
            { label: "VirusTotal", active: !!VT_KEY, note: "70+ AV engines" },
            { label: "AbuseIPDB",  active: !!ABUSEIPDB_KEY, note: "community abuse reports" },
            { label: "OTX",        active: !!OTX_KEY, note: "threat pulses" },
          ].map(k => (
            <span key={k.label} className={`inline-flex items-center gap-1.5 text-[11px] px-2 py-1 rounded-full border font-medium ${
              k.active
                ? "border-green-500/40 bg-green-500/10 text-green-400"
                : "border-border/40 bg-muted/30 text-muted-foreground"
            }`}>
              <span className={`h-1.5 w-1.5 rounded-full ${k.active ? "bg-green-500" : "bg-muted-foreground/40"}`} />
              {k.label} {k.active ? `✓ active (${k.note})` : "— no key"}
            </span>
          ))}
        </div>
      </div>

      <Tabs defaultValue="single" className="mb-0">
        <TabsList className="mb-6 bg-card/60">
          <TabsTrigger value="single" className="gap-1.5"><Search className="h-3.5 w-3.5" /> Single IOC</TabsTrigger>
          <TabsTrigger value="batch" className="gap-1.5"><Database className="h-3.5 w-3.5" /> Batch Lookup</TabsTrigger>
          <TabsTrigger value="cases" className="gap-1.5"><FolderOpen className="h-3.5 w-3.5" /> Cases</TabsTrigger>
        </TabsList>

        <TabsContent value="batch">
          <BatchLookupTab />
        </TabsContent>

        <TabsContent value="cases">
          <CaseManagementTab />
        </TabsContent>

        <TabsContent value="single">

      {/* Search */}
      <Card className="mb-6 border-primary/30 shadow-md">
        <CardContent className="pt-4 pb-4">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                ref={inputRef}
                className="pl-9 font-mono text-sm h-11"
                placeholder="IP · CVE · domain · hash · email · company name (e.g. micron, adobe.com)"
                value={query}
                onChange={e => setQuery(e.target.value)}
                onKeyDown={e => e.key === "Enter" && run()}
              />
            </div>
            <Button onClick={() => run()} disabled={loading || !query.trim()} className="h-11 px-6 gap-2">
              {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
              {loading ? "Scanning…" : "Scan"}
            </Button>
          </div>
          {progress > 0 && <Progress value={progress} className="mt-3 h-1" />}

          {/* Example badges */}
          <div className="mt-3 flex flex-wrap gap-2 items-center">
            <span className="text-xs text-muted-foreground">Try:</span>
            {EXAMPLES.map(ex => (
              <button key={ex.value} onClick={() => { setQuery(ex.value); run(ex.value); }}
                className="flex items-center gap-1 rounded border border-border/50 px-2 py-0.5 text-[11px] hover:border-primary/40 hover:bg-primary/5 transition-colors">
                <span className="text-primary font-semibold">{ex.label}</span>
                <span className="text-muted-foreground">{ex.hint}</span>
              </button>
            ))}
          </div>

          {/* History */}
          {history.length > 0 && !result && (
            <div className="mt-3 flex flex-wrap gap-1.5 items-center">
              <Clock className="h-3 w-3 text-muted-foreground" />
              {history.slice(0, 8).map(h => (
                <button key={h} onClick={() => { setQuery(h); run(h); }}
                  className="rounded px-2 py-0.5 text-[11px] font-mono border border-border/40 text-muted-foreground hover:border-primary/40 hover:text-foreground transition-colors">
                  {h.length > 32 ? h.slice(0, 32) + "…" : h}
                </button>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Results */}
      {result && verdict && (
        <div className="space-y-5">

          {/* Verdict banner */}
          <Card className={`border-2 ${verdict.bg}`}>
            <CardContent className="p-4">
              <div className="flex items-center gap-4 flex-wrap">
                <verdict.icon className={`h-10 w-10 shrink-0 ${verdict.color}`} />
                <div className="flex-1">
                  <div className={`text-2xl font-bold tracking-tight ${verdict.color}`}>{verdict.label}</div>
                  <div className="text-sm text-muted-foreground mt-0.5">
                    {result.type === "keyword" || result.type === "domain"
                      ? `${result.positives} of ${result.total} sources found breach/leak data`
                      : `${result.positives} of ${result.total} sources flagged this observable`}
                  </div>
                </div>
                <div className="text-right space-y-1">
                  <div className="flex items-center gap-1.5 justify-end">
                    <TypeIcon className="h-4 w-4 text-muted-foreground" />
                    <Badge variant="outline" className="font-mono text-[11px]">{result.type.toUpperCase()}</Badge>
                  </div>
                  <div className="flex items-center gap-1 font-mono text-sm">
                    <span className="text-muted-foreground max-w-[200px] truncate">{result.value}</span>
                    <CopyBtn value={result.value} />
                  </div>
                </div>
              </div>

              {/* Weighted threat score bar */}
              <div className="mt-4">
                <div className="flex justify-between text-xs text-muted-foreground mb-1">
                  <span>Weighted Threat Score</span>
                  <span className="font-mono font-bold">
                    {result.score ?? 0}/100 · {result.positives} of {result.total} sources flagged
                  </span>
                </div>
                <div className="h-2.5 rounded-full bg-muted overflow-hidden">
                  <div className={`h-full rounded-full transition-all duration-1000 ${
                    result.verdict === "malicious" ? "bg-destructive" :
                    result.verdict === "suspicious" ? "bg-warning" :
                    result.verdict === "unknown" ? "bg-muted-foreground/40" : "bg-success"
                  }`} style={{ width: `${Math.min(100, Math.max(result.score ?? 0, result.verdict === "unknown" ? 8 : 0))}%` }} />
                </div>
                <p className="text-[10px] text-muted-foreground mt-1">
                  Score ≥70 = Malicious · ≥30 = Suspicious · 0 sources flagged = No Data · Known-good signals reduce score
                </p>
              </div>

              {/* Warning for unknown/clean — don't let users think "no data" = "safe" */}
              {(result.verdict === "unknown" || result.verdict === "clean") && verdict.warning && (
                <div className={`mt-3 flex items-start gap-2 rounded-lg border px-3 py-2.5 text-xs ${
                  result.verdict === "unknown"
                    ? "border-yellow-500/40 bg-yellow-500/8 text-yellow-300"
                    : "border-blue-400/40 bg-blue-400/8 text-blue-300"
                }`}>
                  <AlertTriangle className="h-3.5 w-3.5 shrink-0 mt-0.5" />
                  <div>
                    <span className="font-semibold">{result.verdict === "unknown" ? "No data found — " : "No detections — "}</span>
                    {verdict.warning}
                    <span className="ml-1">
                      Manually verify on{" "}
                      <a href={`https://www.virustotal.com/gui/${result.type === "ip" ? "ip-address" : result.type === "sha256" || result.type === "md5" ? "file" : result.type}/${result.value}`}
                        target="_blank" rel="noopener noreferrer" className="underline font-semibold">VirusTotal</a>
                      {result.type === "ip" && <>{" "}and{" "}<a href={`https://www.abuseipdb.com/check/${result.value}`} target="_blank" rel="noopener noreferrer" className="underline font-semibold">AbuseIPDB</a></>}.
                    </span>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Suspicious Findings — shown above tabs */}
          <SuspiciousFindings result={result} />

          {/* Tabs: Breach | Email Breach | AI Report | Web Search | Sources | Internal DB | External Links | CVE */}
          <Tabs defaultValue={
            result.type === "email"   ? "email"   :
            (result.type === "domain" || result.type === "keyword") ? "breach" : "ai"
          }>
            <TabsList className="bg-card/60 flex-wrap h-auto gap-0.5">
              {(result.type === "domain" || result.type === "keyword") && (
                <TabsTrigger value="breach" className="flex items-center gap-1.5">
                  <AlertOctagon className="h-3.5 w-3.5 text-destructive" /> Breach Intelligence
                </TabsTrigger>
              )}
              {result.type === "email" && (
                <TabsTrigger value="email" className="flex items-center gap-1.5">
                  <AlertOctagon className="h-3.5 w-3.5 text-destructive" /> Breach Details
                </TabsTrigger>
              )}
              <TabsTrigger value="ai" className="flex items-center gap-1.5">
                <Sparkles className="h-3.5 w-3.5 text-primary" /> AI Report
              </TabsTrigger>
              <TabsTrigger value="web" className="flex items-center gap-1.5">
                <Globe className="h-3.5 w-3.5" /> Web Search
              </TabsTrigger>
              <TabsTrigger value="sources">
                <Shield className="mr-1.5 h-3.5 w-3.5" /> Source Results
              </TabsTrigger>
              {result.internalHits.length > 0 && (
                <TabsTrigger value="internal">
                  <Database className="mr-1.5 h-3.5 w-3.5" /> DB ({result.internalHits.length})
                </TabsTrigger>
              )}
              {links.length > 0 && (
                <TabsTrigger value="links">
                  <ExternalLink className="mr-1.5 h-3.5 w-3.5" /> Links ({links.length})
                </TabsTrigger>
              )}
              <TabsTrigger value="attack3d" className="flex items-center gap-1.5">
                <Box className="h-3.5 w-3.5 text-cyan-400" /> Attack 3D
              </TabsTrigger>
              {result.type === "cve" && result.results.nvd?.found && (
                <TabsTrigger value="cve">
                  <Bug className="mr-1.5 h-3.5 w-3.5" /> CVE Detail
                </TabsTrigger>
              )}
            </TabsList>

            {/* Company / Domain Breach Intelligence */}
            {(result.type === "domain" || result.type === "keyword") && (
              <TabsContent value="breach" className="mt-4">
                <CompanyBreachPanel result={result} />
              </TabsContent>
            )}

            {/* Email Breach Details */}
            {result.type === "email" && (
              <TabsContent value="email" className="mt-4">
                <EmailBreachPanel result={result} />
              </TabsContent>
            )}

            {/* AI CTI Report — auto-generates from all enrichment data */}
            <TabsContent value="ai" className="mt-4">
              <div className="mb-2 flex items-center gap-2">
                <Sparkles className="h-4 w-4 text-primary" />
                <span className="text-sm font-bold">AI Threat Intelligence Report</span>
                <span className="text-[10px] text-muted-foreground">· synthesised from {result.total} enrichment sources</span>
              </div>
              <IOCAIReport result={result} />
            </TabsContent>

            {/* MITRE ATT&CK 3D Attack Chain */}
            <TabsContent value="attack3d" className="mt-4">
              <Suspense fallback={<div className="h-[500px] flex items-center justify-center text-muted-foreground text-sm">Loading 3D engine…</div>}>
                <AttackChain3D
                  text={[
                    result.value,
                    result.type,
                    result.verdict === "malicious" ? "malicious threat actor attack" : "",
                    ...Object.values(result.results).map((r: any) =>
                      [r?.threat_type, r?.malware, r?.classification, r?.signature, r?.adversary, r?.threats]
                        .filter(Boolean).join(" ")
                    ),
                    result.type === "ip"     ? "command and control c2 beacon callback infrastructure" : "",
                    result.type === "domain" ? "phishing malware distribution c2 communication" : "",
                    (result.type === "sha256" || result.type === "md5") ? "malware payload dropper execute shellcode" : "",
                    result.type === "cve"    ? "exploit public-facing application privilege escalation" : "",
                    result.type === "email"  ? "phishing credential theft account takeover identity" : "",
                    result.results.feodo?.found    ? "botnet c2 banking trojan" : "",
                    result.results.urlhaus?.found  ? "malware distribution dropper stager" : "",
                    result.results.emerging?.found ? "network intrusion active threat" : "",
                  ].filter(Boolean).join(" ")}
                  title={`Attack chain for: ${result.value}`}
                  autoPlay
                  height="500px"
                />
              </Suspense>
            </TabsContent>

            {/* Web Search — DuckDuckGo/News for this IOC */}
            <TabsContent value="web" className="mt-4">
              <div className="mb-2 flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                <span className="text-sm font-bold">Web Search Results for "{result.value}"</span>
              </div>
              <IOCWebSearch ioc={result.value} />
            </TabsContent>

            {/* Source results */}
            <TabsContent value="sources" className="mt-4 space-y-2">
              {Object.entries(result.results).map(([name, data]) => (
                <SourceRow key={name} name={name} data={data} />
              ))}
            </TabsContent>

            {/* Internal DB hits */}
            {result.internalHits.length > 0 && (
              <TabsContent value="internal" className="mt-4">
                <Card className="border-primary/30">
                  <CardHeader className="pb-2 pt-3 px-4">
                    <CardTitle className="text-sm font-medium flex items-center gap-2">
                      <Database className="h-4 w-4 text-primary" />
                      {result.internalHits.length} articles in ThreatLens referencing this observable
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="px-4 pb-4 pt-0 space-y-3">
                    {result.internalHits.map((item: any) => (
                      <div key={item.id} className="flex gap-3 text-sm border-b border-border/30 pb-3 last:border-0 last:pb-0">
                        <Badge variant="outline" className="shrink-0 text-[10px] self-start mt-0.5">{item.severity?.toUpperCase()}</Badge>
                        <div className="flex-1 min-w-0">
                          <a href={item.link} target="_blank" rel="noopener noreferrer"
                            className="font-medium hover:text-primary hover:underline line-clamp-2 leading-snug">
                            {item.title}
                          </a>
                          {item.excerpt && <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">{item.excerpt}</p>}
                          <div className="text-xs text-muted-foreground mt-1">{item.source_name}</div>
                        </div>
                      </div>
                    ))}
                  </CardContent>
                </Card>
              </TabsContent>
            )}

            {/* External links */}
            {links.length > 0 && (
              <TabsContent value="links" className="mt-4">
                <Card className="border-border/40">
                  <CardContent className="pt-4 pb-4">
                    <p className="text-xs text-muted-foreground mb-3">
                      Open this observable directly in external threat intelligence platforms:
                    </p>
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2">
                      {links.map(l => (
                        <a key={l.label} href={l.url} target="_blank" rel="noopener noreferrer"
                          className="flex items-center justify-between gap-2 rounded-lg border border-border/50 px-3 py-2.5 text-sm font-medium hover:border-primary/40 hover:bg-primary/5 transition-colors group">
                          {l.label}
                          <ExternalLink className="h-3.5 w-3.5 text-muted-foreground group-hover:text-primary transition-colors" />
                        </a>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              </TabsContent>
            )}

            {/* CVE deep-dive */}
            {result.type === "cve" && result.results.nvd?.found && (
              <TabsContent value="cve" className="mt-4 space-y-4">
                {/* CVSS card */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {[
                    { label: "CVSS Score", value: result.results.nvd.cvss_score ?? "N/A", accent: Number(result.results.nvd.cvss_score) >= 9 ? "text-destructive" : Number(result.results.nvd.cvss_score) >= 7 ? "text-warning" : "text-primary" },
                    { label: "Severity", value: result.results.nvd.cvss_severity ?? "N/A", accent: "text-foreground" },
                    { label: "EPSS Score", value: result.results.epss?.found ? `${(result.results.epss.epss_score * 100).toFixed(2)}%` : "N/A", accent: "text-primary" },
                    { label: "CISA KEV", value: result.results.nvd.cisa_kev ? "YES — Exploited" : "No", accent: result.results.nvd.cisa_kev ? "text-destructive" : "text-muted-foreground" },
                  ].map(c => (
                    <Card key={c.label} className="border-border/40 bg-card/40">
                      <CardContent className="pt-4 pb-3">
                        <div className={`text-xl font-bold ${c.accent}`}>{c.value}</div>
                        <div className="text-xs text-muted-foreground mt-0.5">{c.label}</div>
                      </CardContent>
                    </Card>
                  ))}
                </div>

                <Card className="border-border/40">
                  <CardContent className="pt-4 pb-4 space-y-3 text-sm">
                    <div>
                      <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-1">Description</div>
                      <p className="text-foreground/90 leading-relaxed">{result.results.nvd.description}</p>
                    </div>
                    {result.results.nvd.cvss_vector && (
                      <div>
                        <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-1">CVSS Vector</div>
                        <code className="text-xs bg-muted px-2 py-1 rounded font-mono">{result.results.nvd.cvss_vector}</code>
                      </div>
                    )}
                    {result.results.nvd.weaknesses && (
                      <div>
                        <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-1">Weakness (CWE)</div>
                        <span className="text-foreground/80">{result.results.nvd.weaknesses}</span>
                      </div>
                    )}
                    {result.results.epss?.found && (
                      <div className="rounded-lg bg-primary/5 border border-primary/20 p-3">
                        <div className="text-xs font-semibold text-primary mb-1">EPSS Exploitation Probability</div>
                        <div className="text-sm">{result.results.epss.exploitation_probability}</div>
                        <div className="text-xs text-muted-foreground mt-0.5">{result.results.epss.percentile_rank}</div>
                      </div>
                    )}
                    {result.results.nvd.cisa_kev && (
                      <div className="rounded-lg bg-destructive/10 border border-destructive/30 p-3">
                        <div className="font-semibold text-destructive">CISA Known Exploited Vulnerability</div>
                        <div className="text-xs text-muted-foreground mt-0.5">Added to KEV catalog: {result.results.nvd.cisa_kev_date}</div>
                      </div>
                    )}
                    {result.results.nvd.references?.length > 0 && (
                      <div>
                        <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-1">References</div>
                        <div className="space-y-0.5">
                          {result.results.nvd.references.map((r: string) => (
                            <a key={r} href={r} target="_blank" rel="noopener noreferrer"
                              className="flex items-center gap-1 text-primary hover:underline text-xs truncate">
                              <ExternalLink className="h-3 w-3 shrink-0" />{r}
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </TabsContent>
            )}
          </Tabs>

          <p className="text-xs text-right text-muted-foreground flex items-center justify-end gap-2">
            <Clock className="h-3 w-3" />
            Last checked: {lastChecked ? lastChecked.toLocaleTimeString() : "just now"}
            <button className="text-primary hover:underline flex items-center gap-1" onClick={() => run()}>
              <RefreshCw className="h-3 w-3" /> Re-check
            </button>
          </p>
        </div>
      )}

      {/* Empty state — feature cards */}
      {!result && !loading && (
        <div className="space-y-6">
          <div className="grid gap-4 md:grid-cols-3">
            {[
              { icon: Globe, title: "IP Intelligence", items: ["GreyNoise noise/riot classification", "Shodan open ports & CVEs", "Feodo Tracker C2 check", "Pulsedive risk score", "8 external pivot links"] },
              { icon: Lock,  title: "Hash Analysis",   items: ["MalwareBazaar file metadata", "ThreatFox malware family", "Pulsedive threat context", "Links to Hybrid Analysis", "VirusTotal, Any.run"] },
              { icon: Shield,title: "CVE Enrichment",  items: ["NVD CVSS score & vector", "EPSS exploitation probability", "CISA KEV status (exploited?)", "CWE weakness classification", "7 reference / exploit links"] },
            ].map(c => (
              <Card key={c.title} className="border-border/40 bg-card/40">
                <CardContent className="pt-5 pb-4">
                  <c.icon className="h-6 w-6 text-primary mb-3" />
                  <h3 className="font-semibold text-sm mb-2">{c.title}</h3>
                  <ul className="space-y-1">
                    {c.items.map(i => (
                      <li key={i} className="flex items-start gap-1.5 text-xs text-muted-foreground">
                        <span className="text-primary mt-0.5">·</span>{i}
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Recent history */}
          {history.length > 0 && (
            <Card className="border-border/40">
              <CardHeader className="pb-2 pt-3 px-4">
                <CardTitle className="text-sm font-medium flex items-center gap-2">
                  <Clock className="h-4 w-4 text-muted-foreground" /> Recent Lookups
                </CardTitle>
              </CardHeader>
              <CardContent className="px-4 pb-4 pt-0">
                <div className="flex flex-wrap gap-2">
                  {history.map(h => (
                    <button key={h} onClick={() => { setQuery(h); run(h); }}
                      className="font-mono text-xs rounded border border-border/50 px-2.5 py-1 text-muted-foreground hover:border-primary/40 hover:text-foreground transition-colors flex items-center gap-1">
                      <TrendingUp className="h-3 w-3" />{h.length > 40 ? h.slice(0,40)+"…" : h}
                    </button>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>
      )}

        </TabsContent>
      </Tabs>
    </div>
  );
}
